import{_ as t,C as e,c as i,o as a,j as o,b as n,a0 as s,a as r,w as l,G as d,a1 as c}from"./chunks/framework.DKRgXLPU.js";const h=JSON.parse('{"title":"Probability-Based Decision Making","description":"","frontmatter":{},"headers":[],"relativePath":"en/education/tactics/probability.md","filePath":"en/education/tactics/probability.md"}');const u=t({name:"en/education/tactics/probability.md"},[["render",function(t,h,u,b,p,m){const g=e("Mermaid");return a(),i("div",null,[h[1]||(h[1]=o("h1",{id:"probability-based-decision-making",tabindex:"-1"},[r("Probability-Based Decision Making "),o("a",{class:"header-anchor",href:"#probability-based-decision-making","aria-label":'Permalink to "Probability-Based Decision Making"'},"​")],-1)),h[2]||(h[2]=o("p",null,"Elite tactical thinking uses probability to make better decisions. Instead of guessing or going with gut feeling, you think systematically about your options.",-1)),h[3]||(h[3]=o("div",{class:"tip custom-block"},[o("p",{class:"custom-block-title"},"The Big Idea"),o("p",null,[o("strong",null,"Think in probabilities, not certainties."),r(" The best decision isn't always the most aggressive or the safest - it's the one that gives you the best expected value over many similar situations.")])],-1)),(a(),n(c,null,{default:l(()=>[d(g,{id:"mermaid-11",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BDecision%20Point%5D%20--%3E%20B%5BOption%201%5D%0A%20%20%20%20A%20--%3E%20C%5BOption%202%5D%0A%20%20%20%20A%20--%3E%20D%5BOption%203%5D%0A%0A%20%20%20%20B%20--%3E%20E%5BSuccess%20Probability%5D%0A%20%20%20%20B%20--%3E%20F%5BReward%20if%20Success%5D%0A%20%20%20%20B%20--%3E%20G%5BCost%20if%20Failure%5D%0A%0A%20%20%20%20C%20--%3E%20H%5BSuccess%20Probability%5D%0A%20%20%20%20C%20--%3E%20I%5BReward%20if%20Success%5D%0A%20%20%20%20C%20--%3E%20J%5BCost%20if%20Failure%5D%0A%0A%20%20%20%20D%20--%3E%20K%5BSuccess%20Probability%5D%0A%20%20%20%20D%20--%3E%20L%5BReward%20if%20Success%5D%0A%20%20%20%20D%20--%3E%20M%5BCost%20if%20Failure%5D%0A%0A%20%20%20%20E%20--%3E%20N%5BExpected%20Value%5D%0A%20%20%20%20F%20--%3E%20N%0A%20%20%20%20G%20--%3E%20N%0A%0A%20%20%20%20H%20--%3E%20O%5BExpected%20Value%5D%0A%20%20%20%20I%20--%3E%20O%0A%20%20%20%20J%20--%3E%20O%0A%0A%20%20%20%20K%20--%3E%20P%5BExpected%20Value%5D%0A%20%20%20%20L%20--%3E%20P%0A%20%20%20%20M%20--%3E%20P%0A%0A%20%20%20%20N%20--%3E%20Q%5BChoose%20Best%20EV%5D%0A%20%20%20%20O%20--%3E%20Q%0A%20%20%20%20P%20--%3E%20Q%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20Q%20fill%3A%23fff4e1%0A"})]),fallback:l(()=>[...h[0]||(h[0]=[r(" Loading... ",-1)])]),_:1})),h[4]||(h[4]=s('<h2 id="the-basic-framework" tabindex="-1">The Basic Framework <a class="header-anchor" href="#the-basic-framework" aria-label="Permalink to &quot;The Basic Framework&quot;">​</a></h2><p>Every throw has three components:</p><table tabindex="0"><thead><tr><th>Component</th><th>Question</th><th>Example</th></tr></thead><tbody><tr><td><strong>Probability of success</strong></td><td>How likely am I to execute this?</td><td>70% success rate at this distance</td></tr><tr><td><strong>Reward if successful</strong></td><td>What do I gain?</td><td>Win the point, gain position</td></tr><tr><td><strong>Cost if unsuccessful</strong></td><td>What do I lose?</td><td>Give opponent easy point</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">The Formula</p><p><strong>Expected Value = (Probability × Reward) - ((1 - Probability) × Cost)</strong></p><p>Good decisions maximize expected value over time.</p></div><h2 id="thinking-in-probabilities" tabindex="-1">Thinking in Probabilities <a class="header-anchor" href="#thinking-in-probabilities" aria-label="Permalink to &quot;Thinking in Probabilities&quot;">​</a></h2><p>When deciding between options, consider:</p><ul><li>What&#39;s my realistic success rate for each option?</li><li>What do I gain if it works?</li><li>What&#39;s the cost if it fails?</li><li>How does the game situation affect my choice?</li></ul><p>The best option isn&#39;t always the most aggressive or the safest - it&#39;s the one that gives you the best outcome over many similar situations.</p><h2 id="know-your-numbers" tabindex="-1">Know Your Numbers <a class="header-anchor" href="#know-your-numbers" aria-label="Permalink to &quot;Know Your Numbers&quot;">​</a></h2><p>To use probability thinking, you need to know your actual success rates:</p><table tabindex="0"><thead><tr><th>Throw Type</th><th>Distance</th><th>Your Success Rate</th></tr></thead><tbody><tr><td>Point (close)</td><td>6-7m</td><td>___%</td></tr><tr><td>Point (medium)</td><td>8-9m</td><td>___%</td></tr><tr><td>Point (long)</td><td>10m+</td><td>___%</td></tr><tr><td>Shoot (close)</td><td>6-7m</td><td>___%</td></tr><tr><td>Shoot (medium)</td><td>8-9m</td><td>___%</td></tr><tr><td>Shoot (long)</td><td>10m+</td><td>___%</td></tr></tbody></table><p>Track these in practice. Be honest - most players overestimate their success rates.</p><h2 id="adjusting-for-conditions" tabindex="-1">Adjusting for Conditions <a class="header-anchor" href="#adjusting-for-conditions" aria-label="Permalink to &quot;Adjusting for Conditions&quot;">​</a></h2><p>Your base rates change based on:</p><table tabindex="0"><thead><tr><th>Factor</th><th>Effect on Success Rate</th></tr></thead><tbody><tr><td>Unfamiliar terrain</td><td>-10 to -20%</td></tr><tr><td>Pressure situation</td><td>-5 to -15%</td></tr><tr><td>Fatigue</td><td>-5 to -10%</td></tr><tr><td>Confidence (high)</td><td>+5 to +10%</td></tr><tr><td>Recent success</td><td>+5%</td></tr><tr><td>Recent failure</td><td>-5 to -10%</td></tr></tbody></table><p>Be realistic about these adjustments.</p><h2 id="the-boule-advantage-principle" tabindex="-1">The Boule Advantage Principle <a class="header-anchor" href="#the-boule-advantage-principle" aria-label="Permalink to &quot;The Boule Advantage Principle&quot;">​</a></h2><p>When you have more boules remaining than your opponent:</p><p><strong>Priority 1: Secure the point</strong></p><ul><li>First, ensure you&#39;re holding at least one point</li><li>Don&#39;t get greedy before you&#39;ve secured the basics</li></ul><p><strong>Priority 2: Maximize points with calculated risk</strong></p><ul><li>Once you&#39;re holding, assess if you can add more points</li><li>Each additional throw is a risk/reward decision</li><li>Don&#39;t turn a safe 2-point win into a loss by overreaching</li></ul><p><strong>Fewer boules remaining:</strong> You need to make each throw count. Safe plays might not be enough - consider higher-reward options to get back in the end.</p><h2 id="the-une-boule-devant-principle" tabindex="-1">The &quot;Une Boule Devant&quot; Principle <a class="header-anchor" href="#the-une-boule-devant-principle" aria-label="Permalink to &quot;The &quot;Une Boule Devant&quot; Principle&quot;">​</a></h2><p>A boule in front of the jack (between jack and opponent) is extremely valuable:</p><ul><li>It blocks direct pointing lines</li><li>It forces opponents to go around or over</li><li>It can deflect incoming boules</li><li>It&#39;s a &quot;money boule&quot; - worth protecting</li></ul><p><strong>Tactical implication:</strong> Sometimes placing a blocking boule is better than trying to get closest.</p><h2 id="risk-tolerance-by-game-state" tabindex="-1">Risk Tolerance by Game State <a class="header-anchor" href="#risk-tolerance-by-game-state" aria-label="Permalink to &quot;Risk Tolerance by Game State&quot;">​</a></h2><h3 id="with-time-limit" tabindex="-1">With Time Limit <a class="header-anchor" href="#with-time-limit" aria-label="Permalink to &quot;With Time Limit&quot;">​</a></h3><p>When playing with a time limit, score differential matters:</p><table tabindex="0"><thead><tr><th>Score Situation</th><th>Risk Approach</th></tr></thead><tbody><tr><td>Leading by 4+</td><td>Very conservative - protect lead, run the clock</td></tr><tr><td>Leading by 1-3</td><td>Conservative - don&#39;t give away points</td></tr><tr><td>Tied</td><td>Balanced - calculated risks</td></tr><tr><td>Behind by 1-3</td><td>Aggressive - need to gain ground</td></tr><tr><td>Behind by 4+</td><td>Very aggressive - must take chances, time is running out</td></tr></tbody></table><h3 id="without-time-limit" tabindex="-1">Without Time Limit <a class="header-anchor" href="#without-time-limit" aria-label="Permalink to &quot;Without Time Limit&quot;">​</a></h3><p>When there&#39;s no time pressure:</p><ul><li>Stick to your game plan - don&#39;t change strategy just because of the score</li><li>The score will fluctuate - trust your approach</li><li>Only consider changing your game plan if it&#39;s clearly not working against this opponent</li><li>Panic changes when behind often make things worse</li></ul><h3 id="end-game-adjustments" tabindex="-1">End-Game Adjustments <a class="header-anchor" href="#end-game-adjustments" aria-label="Permalink to &quot;End-Game Adjustments&quot;">​</a></h3><p><strong>If winning this end wins the game:</strong></p><ul><li>Be more conservative</li><li>Don&#39;t risk giving away multiple points</li><li>A single point might be enough</li></ul><p><strong>If losing this end loses the game:</strong></p><ul><li>Take bigger risks</li><li>Need to score multiple points</li><li>Safe play won&#39;t save you</li></ul><h2 id="common-probability-mistakes" tabindex="-1">Common Probability Mistakes <a class="header-anchor" href="#common-probability-mistakes" aria-label="Permalink to &quot;Common Probability Mistakes&quot;">​</a></h2><h3 id="_1-overconfidence" tabindex="-1">1. Overconfidence <a class="header-anchor" href="#_1-overconfidence" aria-label="Permalink to &quot;1. Overconfidence&quot;">​</a></h3><p>&quot;I can make that shot&quot; - but can you make it 7 times out of 10? Be honest.</p><h3 id="_2-ignoring-base-rates" tabindex="-1">2. Ignoring Base Rates <a class="header-anchor" href="#_2-ignoring-base-rates" aria-label="Permalink to &quot;2. Ignoring Base Rates&quot;">​</a></h3><p>Your shooting percentage doesn&#39;t change because the moment is important.</p><h3 id="_3-sunk-cost-fallacy" tabindex="-1">3. Sunk Cost Fallacy <a class="header-anchor" href="#_3-sunk-cost-fallacy" aria-label="Permalink to &quot;3. Sunk Cost Fallacy&quot;">​</a></h3><p>&quot;I&#39;ve already missed twice, I should keep shooting&quot; - each throw is independent.</p><h3 id="_4-outcome-bias" tabindex="-1">4. Outcome Bias <a class="header-anchor" href="#_4-outcome-bias" aria-label="Permalink to &quot;4. Outcome Bias&quot;">​</a></h3><p>A risky shot that worked was still risky. A safe play that failed was still correct.</p><h3 id="_5-ignoring-opponent-s-options" tabindex="-1">5. Ignoring Opponent&#39;s Options <a class="header-anchor" href="#_5-ignoring-opponent-s-options" aria-label="Permalink to &quot;5. Ignoring Opponent&#39;s Options&quot;">​</a></h3><p>Consider what they&#39;ll do after your throw, successful or not.</p><h2 id="practical-application" tabindex="-1">Practical Application <a class="header-anchor" href="#practical-application" aria-label="Permalink to &quot;Practical Application&quot;">​</a></h2><h3 id="before-each-throw" tabindex="-1">Before Each Throw <a class="header-anchor" href="#before-each-throw" aria-label="Permalink to &quot;Before Each Throw&quot;">​</a></h3><ol><li><strong>Identify options</strong> (point, shoot, block, etc.)</li><li><strong>Estimate success probability</strong> for each</li><li><strong>Consider outcomes</strong> (success and failure)</li><li><strong>Factor in game state</strong> (score, boules remaining)</li><li><strong>Choose</strong> the option with best expected value</li><li><strong>Commit fully</strong> - no second-guessing during execution</li></ol><h3 id="building-intuition" tabindex="-1">Building Intuition <a class="header-anchor" href="#building-intuition" aria-label="Permalink to &quot;Building Intuition&quot;">​</a></h3><p>Over time, probability thinking becomes intuitive:</p><ul><li>Track your results honestly</li><li>Review decisions after games</li><li>Notice patterns in your success rates</li><li>Adjust your mental model</li></ul><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to &quot;Key Takeaway&quot;">​</a></h2><blockquote><p>Good decisions don&#39;t always lead to good outcomes. But good decisions over time lead to better results.</p></blockquote><p>Think in probabilities. Know your numbers. Make the smart play, not the hopeful one.</p>',59))])}]]);export{h as __pageData,u as default};
